insert into seed_moments (need_id, passage_id, youtube_id, at_s, end_s, title, quote, score) values
  ('same-sin', 112687, 'w-Nb7lByMxg', 386.7, 426.41, 'Victory over sin', 'God is aware of the fact that sin has the intention to make you captive. So he provided a solution for us to live in victory over sin.', 0.603),
  ('same-sin', 42845, 'LERlOg7jRVg', 6380.62, 6442.35, 'Grace gives capacity', 'When you activate the grace of God the spirit of God is mobilized to become active in your life to give you the capacity to live up to the expectation of the requirements of God.', 0.587),
  ('same-sin', 108144, 'tvfY45eL7gk', 6702.45, 6876.48, 'Grace brings victory over sin', 'If you have accepted the operating system called grace, the first evidence you should bring to the table is victory over sin. So you will stay in prayer and fasting until you see victory over that thing.', 0.586),
  ('same-sin', 23146, 'As_EMmOnAFU', 17293.32, 17413.15, 'Bring your body under', 'The first place to use your faith is to bring your body under and bring your appetite under subjection lest at any time after preaching to others you yourself should be a cast away.', 0.584),
  ('same-sin', 35497, 'HVsMjfXyUh0', 7022.36, 7109.32, 'A sign of deflation', 'When you notice things that are sinful and you attracted to them, it''s a sign that you have a flat tire.', 0.581),
  ('fear', 58208, 'TGHYMuHLni8', 9382.84, 9457.08, 'Afraid for too long', 'You have been afraid for too long. You have been waiting, will you stand up and fight?', 0.551),
  ('fear', 44442, 'MCn5cZLdTr4', 9964.84, 10161.83, 'Fear blots faith', 'So fear is a doubt. It''s a doubt that is shot at your heart so that your capacity for faith will either be blotted out or reduce considerably such that in the situation in the circumstance you will lack the ability to turn things around.', 0.581),
  ('fear', 33834, 'GKjIC36hWs0', 4870.28, 4902.93, 'Quietness and confidence', 'In quietness and in confidence shall be your strength. In returning and in rest.', 0.57),
  ('fear', 39318, 'JaSacSvK7oc', 1507.47, 1643.52, 'Fear becomes confidence', 'In the fear of the Lord is strong confidence.', 0.565),
  ('fear', 59729, 'U7St1laOkvs', 9729.28, 9837.83, 'Trust unlocks power', 'If you can trust in me, if you can trust in God, can you trust him? Most of the times it''s because we can''t trust God that is why we can''t see his power.', 0.56),
  ('waiting', 8630, '3GMPretrMfw', 1503.1, 1666.51, 'Do not give up waiting', 'The answer may not come at your own time, it may not come at your own time, but don''t give up. You are not to give up, keep at it, keep praying until the answer arrive.', 0.607),
  ('waiting', 56487, 'SHYeNjhfl7g', 9044.29, 9190.55, 'Give God more time', 'But if you give God some more time, if you allow God to finish the job he is doing, the finished product will be good.', 0.622),
  ('waiting', 166290, 'N0Oo4G5y7bw', 10689.32, 10753.61, 'A marathon, not a sprint', 'Your walk with Jesus is a marathon. It''s not a sprint. It will take time for you to know the ways of God.', 0.68),
  ('waiting', 114977, 'xN_aASAP7sM', 3026.04, 3101.44, 'God said not yet', 'The first year I waited on God he said not yet, I said okay maybe it''s the next year. The next year I waited patiently he said not yet.', 0.57),
  ('waiting', 17100, '7pitC_dLRA4', 5281.38, 5393.27, 'No need to hurry', 'We are not in a hurry because we know that if we take off in a hurry like a tornado we are still going to crash land so there''s no need to be in a hurry.', 0.553),
  ('waiting', 38566, 'JBfHu1nlqd4', 2690.99, 2796.58, 'Stay in the last command', 'Waiting upon the Lord will require that you quieting the noise in your soul and stay in the place of the last command that God gave you.', 0.6),
  ('prayer', 70493, 'Zhz4TUHRmp0', 3168.67, 3267.59, 'Designed to pray', 'Men ought always to pray and not to faint. It means by an act of God''s design for your life you were designed a creature of prayer.', 0.629),
  ('prayer', 58379, 'TMkJ9kl6Ol4', 609.99, 695.17, 'Give ourselves continually', 'We will give ourselves continually to prayer. It doesn''t matter whether you are seeing results if you can be persistent just continue.', 0.603),
  ('prayer', 83452, 'gObEzZzk0ec', 1811.72, 1847.41, 'Grace for consistency', 'I desire, Lord, I desire let the grace for consistency let the spirit of prayer, let it come upon me that I will stay consistent in the place of Prayer.', 0.588),
  ('prayer', 32364, 'Fn7zxRfu8Xg', 606.52, 745.49, 'Allocation for prayer', 'You should have an allocation for prayer. Apart from the one that we do in the congregation, you must have something personal that you sustain in the privacy of your closet.', 0.576),
  ('prayer', 26830, 'CnZ2P08jqHI', 11311.84, 11380.15, 'Habit of prayer', 'You want to develop a habit, a habit of prayer, and the way you develop habit is frequency of Engagement.', 0.616),
  ('prayer', 80485, 'e_PUWxuC-Oc', 4266.64, 4407.51, 'Pray much', 'You will have to pray much, very much, very much if you want to keep Pace with God. Your spirit man must be exercised on a daily basis continually, it must be exercise.', 0.614),
  ('prayer', 58648, 'TWiVZeKhO2w', 1905.08, 1975.51, 'Prayer takes consistency', 'It takes doggedness. It takes consistency. It takes going beyond how you feel.', 0.538),
  ('prayer', 26715, 'ClWul-FQkXY', 2822.52, 2899.33, 'Prayer no longer a burden', 'It will take you like 3 years of consistent prayer before the spirit of Supplication comes upon you, that spirit will drive you throughout your entire life, prayer will no longer be a burden so get to work.', 0.56),
  ('prayer', 70142, 'Za8iQxitN0M', 12222.13, 12338.03, 'Prayer should be a habit', 'It should be your tradition, it should be your habit, and then you should also have a habit, a time where you fast. You don''t wait until you dream a very dangerous dream in the night before you stumble into prayer.', 0.62),
  ('hear-god', 87343, 'imTmTO5kXQU', 6773.74, 6952.55, 'My sheep hear my voice', 'My sheep hears my voice, my sheep hears my voice so if you are born again if you are a sheep of the Lord the capacity to hear God is embedded in you.', 0.653),
  ('hear-god', 60422, 'UJr5k89GR0g', 14619.77, 14684.92, 'Led by the Spirit', 'As many as are led by the spirit of God they are the sons of God so you cannot be a Christian who does not understand Divine leading not just as a subject not just as a teaching but as an experience of your life.', 0.669),
  ('hear-god', 92877, 'lYnARckyDbU', 3193.34, 3252.76, 'Hearing God is not a puzzle', 'I want to demystify the concept of hearing God because many of us we feel paranoid we feel frightened when they say learn to hear God it is not a mystery it is not a puzzle.', 0.637),
  ('hear-god', 82104, 'fSebj4lqd3A', 7820.04, 7941.76, 'Hear him clearly', 'The advantage that we draw from the Holy Spirit is largely determined by our ability to hear him clearly. I''ve said it before what separates the boys from the men is hearing.', 0.635),
  ('hear-god', 32071, 'FcgfcNH6A0w', 929.49, 1029.21, 'Discern scripture’s voice', 'The secret to identifying the voice of God is being able to discern the voice of scripture.', 0.68),
  ('hear-god', 36741, 'IBDYlSXTMYA', 1171.61, 1257.03, 'Know the original voice', 'My sheep heareth my voice. And this is very cardinal. If you have not heard the original voice, you can''t understand the counterfeit.', 0.661),
  ('hear-god', 97210, 'o8JC6NPLbmg', 9591.16, 9771.45, 'Witness confirms truth', 'Everything or anything that you ever receive that is devoid of witness is not from God. Because this spirit that the Bible reveals brings witness.', 0.639),
  ('hear-god', 63509, 'Vx3ETTnJHqc', 3691.1, 3768.6, 'Getting hold of God’s voice', 'That day I went and my life changed from that time till now when I got hold of the voice of God is the best thing that can ever happen to a man that you know his voice.', 0.638),
  ('hear-god', 967, '-UGx0cUUT6o', 7317.39, 7371.71, 'Refined hearing helps', 'If you order your life and the reason why you are fasting is because you want the voice of God to become clear to your spirit, God will come to you.', 0.633),
  ('shame', 16412, '7_wZ9AS4rsE', 12724.48, 12833.33, 'Confess to stay covered', 'If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness. That''s how to stay under a covering.', 0.561),
  ('shame', 59908, 'UBKfaq5oIuE', 10671.01, 10832.32, 'Forgiveness is judicial', 'Forgiveness is not a feeling, forgiveness is a Judicial fact.', 0.569),
  ('shame', 1883, '01afNUcBaUA', 3877.65, 4021.75, 'Apology is not repentance', 'As long as you are giving excuses that justify the action and the deed, that was an apology; that wasn''t repentance.', 0.565),
  ('anxiety', 30581, 'ErrOlOfwEC8', 7191.02, 7305.87, 'Push you into prayer', 'The same things that should make you anxious as the same insufficiencies that should push you into prayer. He said do not be anxious about anything.', 0.655),
  ('anxiety', 45354, 'MiE70TINsJo', 1485.49, 1563.61, 'Pray when overwhelmed', 'The same situations for which you can be anxious are the same situations for which you should pray. The accurate response to situations when you notice that you are overwhelmed and your capacity has been undermined you are being called to the place of prayer.', 0.633),
  ('anxiety', 67892, 'YGnx3g5xOzQ', 2129.2, 2232.91, 'Peace of God', 'Be careful for nothing but in everything by prayer and supplication with Thanksgiving let your request be made known unto God and the peace of God which pass all understanding shall keep your hearts and your minds through Christ Jesus.', 0.338),
  ('anxiety', 60488, 'UKYh3Ggs7P8', 8073.28, 8155.36, 'Prayer instead of anxiety', 'Be anxious for nothing but in everything through prayer and supplication let your request be made known unto God.', 0.631),
  ('anxiety', 116665, 'yRVjjUF6IiU', 8898.79, 9071.79, 'Anxiety opens the door', 'Be anxious for nothing because anxiety is a doorway into the control and the manipulation of the devil.', 0.626),
  ('anxiety', 21941, 'AJulM8y_Y5k', 4522.6, 4756.95, 'Switch to prayer', 'Switch to prayer. And then God will supply his peace from heaven.', 0.617),
  ('purpose', 65207, 'WdNoVnJ_f9Q', 1430.81, 1480.9, 'Meaning is in Him', 'The meaning of your life is not in your life. The meaning of your life is in Him, wisdom demands that you need to consult Him to find out what the meaning of your life is about.', 0.595),
  ('purpose', 87205, 'ij-oevrVhqk', 2186.05, 2247.78, 'Meaning on Christ''s heart', 'I don''t have a meaning until I pick it from the heart of Christ, my meaning, my essence, my relevance, my importance, the reason why I''m here is on the Heart of Jesus.', 0.596),
  ('purpose', 79924, 'eDsDHFjvXCw', 7417.24, 7497.13, 'Purpose is why you exist', 'Purpose is the reason for which something exists. Purpose is the reason for which something is created. Purpose is the reason for which you alive.', 0.59),
  ('purpose', 77159, 'cyTkwkLjtEE', 5228.43, 5273.57, 'A plan before you showed up', 'It is only in Christ that you will know that there was a plan for you before you showed up, because he chose us in him before the foundation of the world.', 0.563),
  ('purpose', 73307, 'bEotcZAGxP8', 3475.04, 3517.17, 'Here to fulfill God''s will', 'If you are a child of God, there is something called the will of God that you are here on this Earth to fulfill.', 0.549),
  ('purpose', 30313, 'Ei4B2ep_e54', 15553.98, 15659.74, 'Created for his kingdom', 'The reason for which God created man is so that he can participate in his kingdom. He can become a personality, part of the infrastructure that helps administer God''s will upon the face of the earth.', 0.545),
  ('purpose', 4920, '1SP78r9JkmI', 10317.36, 10429.93, 'Will of God and assignment', 'Finding the will of God for your life has everything to do with your life''s assignment. God need men everywhere, scriptures command productive living.', 0.576),
  ('purpose', 71688, 'aAo91lvSue4', 3422.72, 3521.12, 'Destiny in God''s heart', 'My destiny first of all reaches into the heart of God to fully articulate what God conceived about me before I was made manifest upon the face of the Earth.', 0.575),
  ('purpose', 71682, 'aAo91lvSue4', 2539.34, 2578.3, 'Please God in living', 'The objective of my living today should be to please God, and if that is the objective we cannot avoid studying the life of Jesus because in Jesus God was satisfied.', 0.592),
  ('purpose', 54395, 'RG2nnvXKKHY', 766.68, 885.26, 'The voice unveils purpose', 'Whenever you come in contact with the voice of God, it has the tendency to unveil the purpose of God.', 0.578),
  ('purpose', 5615, '1ep-JQj-R68', 25016.73, 25055.6, 'Love the Lord dangerously', 'Love the Lord and seek to do his will. Love the Lord dangerously, love him, be ready, be ready to do anything he asks you.', 0.552),
  ('temptation', 75961, 'cF8V0OCaqyw', 12136.36, 12172.43, 'Master the flesh', 'All temptation is? Flesh related. It means that if I master my flesh, I will live a life that has victory over temptation any day, any time.', 0.611),
  ('temptation', 110846, 'vDGYxo9qseY', 773.56, 923.35, 'Temptation takes you away', 'Temptation is designed to take you away from God.', 0.644),
  ('temptation', 66503, 'XSEHkBEQDqg', 21886.39, 21945.87, 'Put desires to death', 'The temptations will keep coming, but the principle of bearing the cross is casting every such desire to death.', 0.568),
  ('temptation', 42345, 'KuxKVO-KRK8', 5874.45, 5936.75, 'Do not partner with Satan', 'The only way the temptation can fulfill its objective in my life is if at some point I partner with Satan.', 0.582),
  ('temptation', 79587, 'eBDIPj6OQp0', 3254.36, 3378.15, 'Do not prove yourself', 'Satan is trying to make Jesus act apart from his father. Satan is trying to make Jesus feel that there''s something you need to prove.', 0.552),
  ('temptation', 107680, 'tpySrZwGu-U', 1080.72, 1240.67, 'Loyalty tested by temptation', 'If you yield to a certain Temptation it is proof that there are things in your life that are more dear to you than your loyalty to Jesus.', 0.621),
  ('temptation', 18059, '8G7IDqHiXKU', 9167.3, 9295.15, 'Drawn away by lust', 'Every man is tempted when he''s drawn away of his own lust and is enticed.', 0.591),
  ('temptation', 110904, 'vFW8dA_3FMk', 1166.67, 1258.53, 'Live by God''s word', 'By design man was ordained to live not by bread alone but by every word that proceeds out of the mouth of God.', 0.587),
  ('temptation', 95080, 'mcJGxUuJu7g', 2843.64, 2895.07, 'Discover the war', 'There is a war that you must discover in you. Many don''t look in this direction, they just glide in the Holy Ghost, but Satan is waiting for a moment to strike.', 0.566),
  ('discouraged', 4503, '1HuLhonkKNE', 11419.02, 11556.83, 'One day at a time', 'Take it one day at a time. The mercies of God, they are new every morning.', 0.563),
  ('discouraged', 58058, 'TDVokmH0WAw', 6459.78, 6494.4, 'Satan discourages you', 'Satan will do everything to discourage you. He will do everything to make you feel that God lied to you.', 0.588),
  ('discouraged', 19074, '8iaDksRc3lY', 5085.96, 5156.82, 'Destroy little foxes', 'We have to destroy the little foxes, those little niggling doubts before they become into fullblown discouragement and make us give up.', 0.339),
  ('discouraged', 10820, '4JtEzglkf0I', 3332.45, 3385.47, 'Keep on pushing', 'Just keep on pushing. Hanah was mistaken for a drunkard even by a prophet, but she kept on pushing.', 0.332),
  ('discouraged', 105621, 'sg4E7Bp3cuQ', 6919.27, 7043.28, 'Run with patience', 'Let us run with patience the race which is set before us.', 0.561),
  ('discouraged', 79864, 'eDoTV7CBRUs', 1924.72, 1977.39, 'Don’t be discouraged', 'Don''t be discouraged, don''t be tired. Sometimes when you begin to break through you begin to feel tired, it is not God it is the devil.', 0.607),
  ('discouraged', 23671, 'BA0nf3dVMBU', 4655.72, 4771.06, 'Faith needs endurance', 'Journey of faith is a journey of endurance, because what the word is doing is the word is bringing pressure upon us.', 0.564),
  ('future', 24374, 'BRrnT1aJ5Kg', 5525.42, 5563.53, 'Not afraid of tomorrow', 'This love I''m talking about is an anchor is the reason for which you are not afraid of tomorrow because one that is already in tomorrow is in love with you.', 0.487),
  ('future', 81691, 'fHB4MwUrYuU', 12598.92, 12634.4, 'Light in darkness', 'You will do well if you take heed as onto a light that shines in a dark place until the day dawns and the day star rises in your heart.', 0.512),
  ('future', 32434, 'FnR9ft2s9J0', 7738.44, 7828.77, 'The end shall be glory', 'I didn''t know how the journey was going to be but there''s one lady who told me said the end shall be glory and I believed it and I held on to it that the end shall be glory.', 0.467),
  ('future', 51041, 'PXJp-TsydV4', 6549.72, 6600.28, 'Trust not man', 'Trust not a man let your confidence not be in the sons of men.', 0.326),
  ('future', 39685, 'JkmoyoGImY0', 1933.78, 2067.98, 'Journey starts in hope', 'When you have no other hope but God that''s when the journey start.', 0.458),
  ('future', 58188, 'TGHYMuHLni8', 6267.08, 6301.28, 'Look at the right place', 'You know where you are looking in a time like this is going to determine where you are going to end up with. Don''t look at the wrong place.', 0.334),
  ('dryness', 63185, 'Vn_I_UvMLRc', 353.12, 435.95, 'Freshness in His presence', 'If you dwell in his presence there is a freshness that saturates your entire being. Hallelujah.', 0.582),
  ('dryness', 35621, 'HZsZfMCPpos', 1045.06, 1123.08, 'Time of refreshing', 'Time of refreshing shall come from the presence of the father. Amen.', 0.619),
  ('dryness', 66638, 'XU-weol4uho', 1330.74, 1385.3, 'Prayer brings life', 'The more you pray, the more alive you become in the spirit. There is a Consciousness that is born on your inside that impacts the sense of assurance.', 0.56),
  ('dryness', 47891, 'Np3844Yh79E', 2173.07, 2212.35, 'Short of the Holy Ghost', 'You are short of the Holy Ghost, it''s an emergency. You have to look for Him because it is only Him.', 0.607),
  ('dryness', 48161, 'NxPwjxeuFTM', 1091.4, 1176.44, 'Press through the drought', 'That believer that doesn''t have the strength to press through that drought never gets to the point where it becomes quickened, and if you are not quickened you will not be able to discern God.', 0.608),
  ('dryness', 111764, 'vZL8TQ9x7Gk', 2743.49, 2785.45, 'Rise again spiritually', 'That which I had in my spirit has to rise again in order for me to maintain and to build my spiritual life again I had to disconnect from everything around.', 0.553),
  ('dryness', 31528, 'FNhbFaJObjc', 6429.85, 6579.72, 'Dryness makes you vulnerable', 'Then you go on with dryness and you become vulnerable spiritually.', 0.574),
  ('marriage', 19615, '95wvmQHBv8M', 6561.29, 6613.06, 'Agree on your home', 'It is imperative that both of you sit down to agree and plan how you want to live your home, your lives together. Now that is going to be unique to the two of you.', 0.588),
  ('marriage', 115418, 'xpMv6fzWs0g', 4801.84, 4911.05, 'Choose a proven believer', 'Don''t marry sister, don''t marry a man that has no history in God. The man that got born again yesterday and he wants to marry you, no don''t marry.', 0.534),
  ('marriage', 93877, 'm8b9IE3D0CI', 8805.24, 8927.41, 'Sacrificial living', 'Marriage is a call to sacrificial living. We need to cooperate with God by making sacrifices to enable him raise godly seed.', 0.647),
  ('marriage', 41299, 'KTKDNWFoU7o', 2548.65, 2660.83, 'Shift your gaze', 'Why are so many marriages failing in our generation? You see, it''s a calculated attack from the pit of Hell very calculated, and this happens when we shift our gaze away from Jesus.', 0.562),
  ('marriage', 3018, '0YToTvrABtw', 9278.94, 9445.39, 'Insist on sexual purity', 'Insist on sexual purity. I am telling you that the thing doesn''t end with marriage, we are still fighting the battle every day, it''s a decision.', 0.6),
  ('marriage', 14756, '6a_UWJSaHYY', 3016.66, 3173.8, 'Marriage is a covenant', 'Marriage is not a contract, marriage is a covenant. A covenant that joins you with a people. It''s a covenant that joins you with the spiritual atmosphere of the people.', 0.597),
  ('marriage', 47490, 'NbPDXb-T71Q', 9888.87, 9940.27, 'Respect is covenantal', 'The Bible says a woman should respect her husband. You think that has nothing to do with the cross, it''s part of the Covenant.', 0.589),
  ('marriage', 116165, 'yDE97QygfsM', 7971.67, 8010.1, 'Learn submission early', 'Anything you struggle with before getting into marriage you struggle with it in marriage. If you are struggling with submission in your family amongst your parents, your siblings, they tell you to do something, I want to do it at my own time.', 0.587),
  ('forgive', 91655, 'l354h5ToTv0', 3430.56, 3491.43, 'Begin the process by forgiving', 'In order for the Holy Spirit to go and effect a healing, you must begin the process by forgiving. The next 5 minutes I''d like you to forgive everybody.', 0.59),
  ('forgive', 49461, 'OXqqo5x4LBk', 13947.57, 14069.46, 'Show mercy and release', 'Until you''re willing to show mercy, you can''t merit mercy. Lord, I''m ready to forgive and release.', 0.558),
  ('forgive', 1887, '01afNUcBaUA', 4468.72, 4560.69, 'Unlimited forgiveness', 'You can never keep loving until you offer each other unlimited forgiveness.', 0.36),
  ('forgive', 105382, 'scgbfRUpFpA', 3767.71, 3827.8, 'Say I forgive', 'Sometimes just saying I forgive breaks the walls and you walk free again. I will walk free, I will walk free.', 0.351),
  ('forgive', 114279, 'wy6YpcW2aNo', 10252.91, 10350.94, 'Willing to let go', 'The Lord is convicting you on the matter of forgiveness and you are willing to obey him to forgive, to let go.', 0.349),
  ('money', 21806, 'A7td-f2vuig', 9191.17, 9260.07, 'God provides needs', 'God had designed a system to guarantee that what to eat what to drink was already provided all man needed to do was to live in that reality and serve the will of God that''s all he needed to do.', 0.547),
  ('money', 646, '-LEOTXXseqw', 9674.29, 9740.0, 'Trusting God is safe', 'Concluded again and again and again that the person that is safe to trust is God. I don''t know what my parents trusted, I don''t know what their own parents trusted, but I found a God for myself and that God is Jehovah.', 0.642),
  ('money', 27418, 'D6MUNGff4Fo', 10813.96, 10968.43, 'Trust God for needs', 'It is the pagans of the world that worry about such things. It''s because you do not trust God enough that he will cover that part of your needs.', 0.571),
  ('money', 40405, 'KBPEpyWcIn0', 2106.16, 2245.47, 'Aligned to his kingdom', 'God is not going to meet your need because you are crying, no he will begin to meet your need because you are aligned to his kingdom.', 0.602),
  ('money', 22502, 'AbIDSZHho1I', 5477.21, 5611.95, 'Prosperity needs wisdom', 'Prosperity is not for idle people, it''s for people that are willing to deploy the wisdom of God and also they have enough courage to follow in the direction of the wisdom of God.', 0.578),
  ('money', 83931, 'gbdG2RzoOFU', 5204.24, 5240.94, 'God trusts faithful stewards', 'The benefit of being hooked up committed financially to a kingdom cause is that God gives you, he can trust you with more resources.', 0.57),
  ('healing', 25159, 'Bt-zSO1nb-s', 3474.24, 3566.58, 'God''s will to heal', 'For every person sick it is God''s will for them to be healed that is why the provision for healing Jesus Christ made it in full.', 0.598),
  ('healing', 51807, 'PmsrJdLc3sY', 6337.44, 6391.91, 'Stripes for healing', 'He was wounded for our transgressions so the wounds were for the transgressions, the bruises were for the iniquities, chastisement was so that we could have peace with God and Stripes was so that we could be healed.', 0.595),
  ('healing', 14920, '6gUmctLdbSU', 4566.88, 4738.03, 'Healing has been paid', 'He paid already. Are you there? That means healing exist in the realm of the spirit as a commodity that has been paid for and is yours.', 0.586),
  ('healing', 83426, 'gOApRgEFEpo', 8732.16, 8767.19, 'Healed by his stripes', 'He was wounded for our transgressions, he was bruised for iniquity, the chastisement of our peace was upon him and with his stripes we were healed.', 0.522),
  ('healing', 112876, 'w9jKqVTtkBQ', 5079.96, 5222.42, 'Prayer makes the sick well', 'And the prayer offered will make the sick person well, and the Lord will raise them up.', 0.579),
  ('healing', 28955, 'E3feDcWnvIc', 5281.92, 5353.49, 'God is a healer', 'If you know that God is a God that heals and you are sick, the conditions are already met because the Healer has no work if there''s no sick person.', 0.562),
  ('rejection', 107903, 'tuWStb-Poq4', 20859.66, 20960.4, 'Tell Him your pain', 'For every emotion I was going through I could come to Him and ask Him for help. I could come to Him and tell Him about the rejection I felt, the struggles I had, the pain I was dealing with.', 0.559),
  ('rejection', 42512, 'L1S2ebzLRTc', 810.36, 897.62, 'You are accepted', 'He reminded me, No, you are not rejected. You are accepted. That your life has value.', 0.525),
  ('rejection', 64368, 'WFrI6npbq_4', 5244.72, 5425.67, 'Closer to destiny', 'Sometimes people reject you in the whole family, and you''re like an outcast. Meanwhile you are closer at that point to destiny.', 0.531),
  ('rejection', 89938, 'kPvJa2iMdp0', 13925.64, 14062.94, 'Afraid of rejection', 'You''re afraid of rejection. Jesus was more rejected than anyone.', 0.513),
  ('rejection', 35927, 'HfOhe_CCubg', 17837.83, 17875.17, 'Rejected vessels', 'The Lord is interested in broken things. He is very much interested in rejected vessels.', 0.499),
  ('rejection', 94819, 'mWRvAjXf7NQ', 8437.19, 8584.09, 'Your union with Christ', 'The understanding of your identity, the understanding of your reality is consistent with your union with Christ.', 0.493),
  ('grief', 109024, 'uGkFiIs7sh0', 9080.89, 9194.51, 'A void is created', 'When you lose someone or something of that nature happens to you there is a void that is created.', 0.618),
  ('grief', 10491, '47uNfIZW5KI', 12623.88, 12801.33, 'Weep not, arise', 'When the Lord saw her, he had compassion on her, and said unto her, Weep not.', 0.557),
  ('grief', 30661, 'EtwURSuKJ94', 8223.03, 8321.75, 'Crying to the Lord', 'Maybe you lost someone and you felt really bad but even though you felt bad you still cry to the Lord.', 0.548),
  ('grief', 78749, 'dgj6n8sLRDY', 10467.95, 10566.27, 'Weep with those who weep', 'Sometimes the person just needs you to understand with them, cry with them if you need to.', 0.562),
  ('grief', 103782, 'ruIU0jNusBI', 1167.64, 1257.83, 'Understanding grief', 'When I lost my brother I now understood the pain and Agony people go through when they lose loved ones.', 0.54),
  ('faith', 88056, 'jEYjPBCrszg', 7528.0, 7600.28, 'God is alive', 'Number one you must believe that the God whom you are putting your faith in is alive, you are not putting your faith in a dead God.', 0.64),
  ('faith', 30789, 'Evk3-2pm8ao', 12479.71, 12539.9, 'Live by faith', 'The way you come in is by faith. The way you stay in is by faith. The way you go on is how? By faith.', 0.686),
  ('faith', 93214, 'lsMH4vzvQEU', 1325.1, 1431.31, 'Faith sees God''s view', 'Faith is that facility that God makes available for you to see things through his own eye view.', 0.641),
  ('faith', 40110, 'K1oTGSidQkQ', 8108.67, 8243.56, 'The spirit of faith', 'The spirit of Faith it will make you see differently, it will make you respond differently, it will make you talk differently.', 0.636),
  ('faith', 61637, 'UwN-Tx0DDXM', 1198.84, 1368.34, 'Faith sees by the Holy Ghost', 'Faith is not blind. It''s just that the sight of faith is a function of your inner eye, which is your ability to see through the Holy Ghost.', 0.686),
  ('faith', 110625, 'v7PZV2cMCpI', 11460.42, 11492.62, 'From faith to faith', 'Our calling is from faith to faith. Is from victory to victory. He calls us to step into new seasons of victory.', 0.672),
  ('faith', 73086, 'b3Vkbelkmsc', 7749.37, 7867.57, 'Faith beyond time', 'Faith takes you beyond the prison and the limitation of time. So you are interacting with things that have not yet been born in time.', 0.665),
  ('faith', 9789, '3lfAzB85wxs', 1324.02, 1357.33, 'Look at the unseen', 'Why we look not at the things which are seen but at the things which are not seen, for the things which are seen are temporal but the things which are not seen are Eternal.', 0.646),
  ('faith', 60024, 'UD0MUzhzqMU', 3126.12, 3194.18, 'Restore your convictions', 'Has something affected your convictions? So much so that you no longer believe the things you used to believe?', 0.554),
  ('presence', 42207, 'KovIMz-sTQk', 1135.16, 1393.22, 'Meeting a person', 'When we come to church, and this is a secret you need to have it in mind, that you are coming to meet with a person, not a set of activities.', 0.625),
  ('presence', 87116, 'ifO4WS421tE', 12975.08, 13034.91, 'Seek His face', 'Don''t you ever come into the presence of God and begin to seek different other things, but seek his face. Seeking the face of God is essential for you to experience the glory of Christ.', 0.633),
  ('presence', 51097, 'PbbziOT2A0k', 2238.32, 2474.17, 'Seek God with your heart', 'You will seek me and you will find me when you seek me with all your heart.', 0.62),
  ('presence', 103088, 'repw6xqE3UU', 5962.06, 6043.47, 'Respect the presence', 'This presence is the reason why I am alive today. If you don''t respect the presence, there are benefits that are in the presence that you''ll not be able to draw out.', 0.593),
  ('presence', 97614, 'oPk7729u0kM', 1545.63, 1619.12, 'Access by indwelling presence', 'The secret to accessing everything that is in God is linked to the indwelling presence of God. It is possible for you to be confessing scriptures in the flesh.', 0.614),
  ('presence', 111309, 'vUkck_y8Hs4', 7279.92, 7511.24, 'God must be searched out', 'But God must be searched out every day and that''s what the flesh does not like.', 0.614),
  ('presence', 17045, '7o9FNOsi_Fc', 7872.07, 7937.77, 'From information to experience', 'When God wants to give you experiences he takes you from the information dimension brings you into the experiential Dimension, and in the experiential Dimension you come under the influence of the spirit of Revelation and the spirit of wisdom.', 0.634),
  ('presence', 15798, '73Zs-hn9YY8', 10775.95, 10838.05, 'Alignment of heart and mouth', 'There is an alignment of heart and mouth that brings him, and God began to teach me that the first thing you need to do is that there must be alignment between what your heart and your mouth. That''s how to seek God.', 0.614),
  ('holiness', 12800, '5Ojfu1htdJ8', 3193.3, 3268.79, 'Obedience after salvation', 'The moment you give your life to Christ you are called to obedience.', 0.67),
  ('holiness', 91338, 'ku1ra94-oLE', 8558.12, 8646.12, 'Holiness in daily life', 'As he which has called you is Holy, so be holy in all manner of conversation.', 0.641),
  ('holiness', 79710, 'eCMeTt4iiAE', 5767.76, 5832.33, 'Holiness starts with Him', 'Holiness starts with Him. That''s His nature, that''s how He is. He cannot deny Himself. If you want a relationship with Him, then you would need to be holy.', 0.608),
  ('holiness', 116787, 'yVWJj6BRjCo', 5157.9, 5193.36, 'Holy means separate', 'What it means to be holy is to be separate, is to be operated by one Spirit.', 0.608),
  ('holiness', 47429, 'N_VaFRNeeoY', 10642.92, 10738.33, 'Holiness makes you different', 'God will make you different, he will not make you popular, he will make you different. What it means to be holy is that you are different.', 0.59),
  ('holiness', 81450, 'f1a6VuWN6WQ', 11529.74, 11611.28, 'Not run by sin', 'When we say that a man is separated unto God, it means that he has decided that Satan will not run him as a computer, sin will not run him.', 0.615),
  ('holiness', 44408, 'MCn5cZLdTr4', 5613.8, 5662.86, 'Separated unto God', 'What is holiness? One, it means that I am separated unto God.', 0.69),
  ('holiness', 29842, 'EaOOJH6BdqU', 3043.69, 3160.52, 'Operated by the Holy Ghost', 'You decide that you be operated only by the Holy Ghost, and your life will be a reflection, a testimony, a revelation of what the Holy Spirit does.', 0.626),
  ('holiness', 65110, 'WdEJUCQu_uo', 448.46, 476.4, 'The price of redemption', 'If you realize the price that was paid for your Redemption, you will consecrate yourself.', 0.605),
  ('holiness', 23013, 'ApE_Wy-SaAQ', 8650.65, 8800.01, 'Want to live right', 'The moment you have in your heart that I want to live right, you will live right.', 0.61),
  ('holiness', 44424, 'MCn5cZLdTr4', 7687.75, 7803.33, 'Sanctify yourselves', 'So holiness has two sides. So this side is sanctify yourselves. That''s consecration. Then the Lord will sanctify you. That is saturation.', 0.637),
  ('grace', 84482, 'gtAuXBU6xss', 5406.67, 5590.26, 'Grace gives enablement', 'In grace, what God does is that he gives us enablement through his spirit to live up to the demands of the law. So what he did in grace was not that he reduced the standard.', 0.631),
  ('grace', 19254, '8tyD17nLsCc', 2013.68, 2052.23, 'Mercy and grace differ', 'The mercy of God takes away from you what you deserve. And the grace of God gives to you what you do not deserve.', 0.658),
  ('grace', 7482, '2_x_IzcQ1sk', 984.16, 1146.74, 'Grace is appropriated by faith', 'So in the book of Ephesians chap 2:8 it says it is by grace that we are saved but it is of Faith right it is through faith that we appropriate Grace.', 0.651),
  ('grace', 110789, 'vAp3XU5FRoI', 5976.74, 6081.9, 'Grace teaches holy living', 'For the grace of God that bringeth salvation has appeared to all men. Next verse. And grace teaches, it teaches us that denying ungodliness and worldliness, we should live soberly, righteously, and godly in this present world.', 0.684),
  ('grace', 106460, 't3runnbXW3M', 1166.64, 1333.75, 'Grace empowers a man', 'Grace of God is manifold and when God wants to empower a man he doesn''t necessarily give him money, gives him Grace it is a Grace that comes upon him that becomes the basis of his influence.', 0.623),
  ('grace', 31671, 'FT-JFEScmG8', 1080.25, 1243.05, 'What I am by grace', 'I am what I am by the grace of God when you begin to grow deeper in this plan of God that is enshrined in the book of Ephesians chapter one then you begin to understand the place of Grace.', 0.642),
  ('grace', 19271, '8tyD17nLsCc', 3847.16, 3989.29, 'Common and saving grace', 'There''s what they call common grace, and then there''s what they call saving grace or redeeming grace. That is common grace which God lavishes upon everybody, both saved and unsaved.', 0.632),
  ('grace', 41100, 'KPcnaSrUpDI', 365.72, 488.08, 'Forgiveness is grace', 'The economy of the New Testament has a provision which no other religion can boast: that they offer. And that''s the provision of forgiveness. One of the things that Grace has made available to us is the provision of forgiveness, forgiveness of sin.', 0.624),
  ('grace', 53957, 'R0xONCY6mDU', 1425.66, 1508.88, 'Grace empowers real works', 'If there is no grace, you are fake. If there is no grace, your works that you are doing in the name of the Lord, they are coming from the energy of the flesh.', 0.662),
  ('self-control', 64377, 'WFrI6npbq_4', 6452.26, 6548.74, 'Yield to the Spirit', 'The Bible recommends that the way out of slavery to sin is that you must yield to the Spirit, and through the Spirit you paralyze the deeds of the body.', 0.662),
  ('self-control', 45061, 'MWDpKV36e3A', 10666.12, 10744.05, 'Power begins with self-control', 'That''s where self-control comes in. You want power. The first lesson God will teach you is self-control.', 0.613),
  ('self-control', 69075, 'Z-tkOcqgow4', 2501.08, 2651.54, 'Beat the body down', 'I beat my body, I put it in subjection. I need you to understand that this is a consistent action of any man that wants to gain mastery because your flesh will fight you to the end.', 0.617),
  ('self-control', 8478, '38D5Pgyu3VY', 1140.94, 1170.17, 'Mastery over appetite', 'The first line of mastery that a young adult must have is mastery over appetite.', 0.645),
  ('self-control', 53305, 'QaBMqju7NQQ', 1586.28, 1696.72, 'Crucified to conquer appetite', 'And the reason why you have authority to conquer all those appetites is because you were crucified with Christ.', 0.641),
  ('self-control', 1425, '-lzeasJFvXI', 2583.36, 2756.76, 'Disciplined in all things', 'Everyone that strives for the Mastery, he is temperate in all things.', 0.609),
  ('self-control', 68337, 'Yao8V16wrzE', 2087.0, 2227.44, 'Be in charge of appetites', 'If you are not in charge of the appetites, you are still subject to manipulation, and hence the need for a regiment in terms of your spiritual exercises so that you can be in charge of your time.', 0.686),
  ('self-control', 2010, '02FxbkyFBds', 857.04, 909.23, 'Say no and repent', 'Anytime you walk in the flesh and the Holy Spirit gives you a signal, you repent, say no, this is not my destiny.', 0.617),
  ('self-control', 115085, 'xZXgOn0plTA', 4401.38, 4576.38, 'Temperate in all things', 'If you are striving for the Mastery, you must be temperate in all things so I can stay without food for many days and if it''s food Satan wants to use to bring me down he will fail.', 0.588),
  ('self-control', 107581, 'tlRiWQ0A_MA', 8277.64, 8307.77, 'Spirit binds the flesh', 'The antidote for the flesh is the spirit of God. It''s only the spirit of God that can bind the flesh.', 0.627),
  ('self-control', 90149, 'kSMvE2AWlTY', 1188.29, 1298.6, 'What controls you', 'The issue of Matthew chapter 6 is mastery. What gains mastery over you? What controls you? What is the government that regulates your life?', 0.637),
  ('purity', 60563, 'UOOKfPeh0Go', 10328.13, 10399.24, 'Pray specifically', 'I learned how to pray specifically naming issues by name, this lust of the flesh.', 0.575),
  ('purity', 103229, 'rkzv9toSXE4', 1415.34, 1538.61, 'Yield to God', 'Nobody can deliver me unless I yield myself to God, and the Bible say yield your instrument unto God.', 0.543),
  ('purity', 46314, 'N7zmssqolHU', 6044.29, 6219.72, 'Enemy of sanctification', 'The greatest enemy of sanctification and saturation is called fornication.', 0.6),
  ('purity', 114788, 'xGFt0hAzo2k', 7740.13, 7880.47, 'You can keep yourself', 'No matter how raging, how slippery, how entangling sex sexual immorality is, no matter how entangling no matter how raging no matter how slippery and enticing it is you can actually resist it, you can actually keep yourself from it.', 0.594),
  ('purity', 57597, 'SwpFEaZKzB0', 391.56, 559.59, 'Desire under God', 'Lust is a desire, a superfluous desire that does not want to be governed by the word of God. The desire itself is legitimate, but it has no it doesn''t recognize the governing power of the word of God.', 0.527),
  ('purity', 91667, 'l354h5ToTv0', 4808.39, 4840.33, 'Take drastic action', 'You would take a drastic action against that lust so that the lust will be straightened back to size.', 0.526),
  ('purity', 166326, 'N0Oo4G5y7bw', 15668.12, 15767.44, 'Bring appetite under subjection', 'Every appetite must be brought in subjection.', 0.587),
  ('drifted', 46683, 'NJWO7U-pmFQ', 4278.36, 4311.74, 'Leaving your altar', 'You can still be speaking in tongues and you are still singing in the choir but the moment you leave the place of your altar that''s the definition of backslide.', 0.557),
  ('drifted', 16168, '7MXhUWJxzBs', 2483.32, 2547.14, 'Remember and repent', 'Remember therefore from whence thou art fallen, and repent, and do the first works, or else I will come unto thee quickly, and I will remove thy candlestick out of his place, except thou repent.', 0.576),
  ('drifted', 108685, 'uCnVuhv82vw', 0.0, 149.46, 'Restore first hunger', 'Your love for God has grown cold you need to ask the Lord restore my first Hunger you knew how you used to pray and fast when you first gave your life to Christ.', 0.539),
  ('drifted', 52436, 'Q3GUGelj7ks', 3463.99, 3617.78, 'No longer find pleasure in sin', 'The ointment used to deal with your hardened heart is God. He brings you to a place where you can no longer find pleasure in sin.', 0.528),
  ('drifted', 115779, 'y4mma6PsEqw', 5080.4, 5134.5, 'Return with repentance', 'Can you return to the Lord with your heart in hand and cry out to the Lord, Lord I come with total repentance this afternoon I come with repentance.', 0.576),
  ('drifted', 37924, 'IupYfZYCgT4', 1588.61, 1657.4, 'Desperate for right standing', 'The first backbone your faith life must have is that you are desperate for right standing with God, desperate, desperate.', 0.446),
  ('delay', 40050, 'K1Q19hHq8Do', 5910.54, 6019.05, 'God cannot lie', 'God is not a man that he should lie. He''s not a son of man that he should repent. There''s no situation that is so big that God will now have to say, Oh did I say that?', 0.615),
  ('delay', 110516, 'v5B9bMmbztQ', 4404.21, 4545.85, 'A promise has a process', 'That''s the kind of process that you are stuck in because that word that came to you is a seed but it will go through a process before it begins to reveal itself.', 0.662),
  ('delay', 35378, 'HJCY8Mu9vzg', 3620.04, 3736.31, 'Endure the process', 'So in order for you to enter into that place where you can receive a promise sometimes is a marathon. So if you don''t have the ability to endure the process many times you miss the prize.', 0.605),
  ('delay', 74023, 'bY-z3bEIuzI', 1296.47, 1434.69, 'Cast not away confidence', 'Cast not away your confidence, the reason why he say cast it not because the possibility of casting it exists. It''s very easy for you to cast it and then you become empty.', 0.57),
  ('delay', 108625, 'uBiS1dW49mE', 5883.2, 5943.97, 'A date for your miracle', 'God is king and he has seasons for everything he wants to do under heaven. There is a date for your miracle.', 0.589),
  ('delay', 104834, 'sNMhhTCJUhg', 10818.77, 10935.56, 'Three stages of promise', 'There are three stages. What God gave in Christ, what you receive in your heart, then what manifest in your life.', 0.577),
  ('delay', 59712, 'U7St1laOkvs', 7563.05, 7693.93, 'Faith does not quit', 'Faith does not quit, faith is a fighter. We wrestle not against flesh and blood, it is by faith that we wrestle for our inheritance.', 0.568),
  ('delay', 74021, 'bY-z3bEIuzI', 1113.47, 1147.53, 'Promises come in season', 'The Bible also reveals that those things that God speaks comes to pass in their season, that means you cannot make it come to pass.', 0.602),
  ('fasting', 40357, 'K7n_7hi3xuk', 704.47, 858.65, 'Fasting weakens the flesh', 'In fasting you are starving your flesh. In fasting you are paralyzing the response time of your flesh.', 0.642),
  ('fasting', 100619, 'q7msJCO4tFM', 10950.4, 11098.05, 'Fasting adds power to prayer', 'A praying Christian is a powerful Christian, but a praying fasting Christian is a more powerful Christian.', 0.62),
  ('fasting', 91543, 'l-L9cNu5Uf8', 1550.32, 1690.51, 'Fast with guidance', 'If you are going to fast more than 21 days, you need to be led to do that.', 0.482),
  ('fasting', 59975, 'UClczako_lY', 5033.8, 5202.6, 'Stuff your spirit', 'Fasting means to starve your flesh so that you can stuff your spirit. You starve your flesh so that when you are under pressure you will not respond from the flesh, but you respond from the spirit that has been stuffed.', 0.636),
  ('fasting', 10999, '4MsXyAvj6HU', 11136.11, 11261.24, 'Cut off breakfast first', 'If you want to find God, cut off breakfast at least, fast in the morning. If you have been fasting breakfast and you want to find Revival, cut off lunch.', 0.576),
  ('calling', 233245, 'vBbSx8qW0oU', 4061.8, 4175.41, 'Grace for your calling', 'When you are called there''s always comes a grace for that calling. 1 Thessalonians 5:24 says, Faithful is He that calleth you, who also will do it.', 0.656),
  ('calling', 72902, 'ayO8Hi8vtrE', 309.5, 359.27, 'Calling is your essence', 'Your calling is a description of your essence and your importance upon the face of the earth.', 0.649),
  ('calling', 108018, 'tuWStb-Poq4', 35586.33, 35743.56, 'Stretch beyond comfort', 'What are the duties that will cause you to stretch beyond your comfort zone? What are the duties you are currently running away from?', 0.656),
  ('calling', 96026, 'nItvrm9j6zo', 8586.42, 8663.51, 'Call received in fellowship', 'It was in Fellowship personally that I''ve received the call of God on my life. I never knew that I have a call.', 0.637),
  ('calling', 4393, '1GOnATDurW4', 1566.52, 1703.35, 'Calling is unique', 'His calling is not in the area of your competence. His calling is to satisfy something that is in his heart.', 0.633),
  ('calling', 14382, '6HlCQ0FtkCI', 18496.64, 18528.62, 'Stay where called', 'The estate wherein God has called you, please stay there and be very faithful. In the final analysis God rewards every man according to their labors.', 0.68),
  ('calling', 116486, 'yLbJD-8tNJ4', 933.02, 1037.43, 'Authority fulfills purpose', 'If God cannot exercise his authority over your life, then he cannot fulfill his divine purpose in your life.', 0.654),
  ('calling', 47185, 'NSKQcg4ZpUA', 7930.08, 8069.37, 'The calling belongs to Jesus', 'So the thing about the calling is that we do not qualify. The calling belongs to Jesus. He would have been fulfilling it if he were physically present.', 0.635),
  ('singleness', 570, '-KU2CmamxI0', 11698.53, 11823.44, 'Spouse attraction matters', 'God knows that it''s important for you to find your spouse attractive so God is not going to lead you into a setup where you will permanently not find your spouse attractive.', 0.668),
  ('singleness', 69078, 'Z-tkOcqgow4', 2851.19, 2965.51, 'God prepared your wife', 'When God spoke to me clearly on my knees, he said I prepared your wife and the way you are going you will never miss it, it means God takes responsibility to present my wife.', 0.633),
  ('singleness', 93859, 'm8b9IE3D0CI', 6219.96, 6272.02, 'God scrutinizes marriage', 'When God wants to bring you into marriage, he runs a panoramic review and investigation into all those dynamics and realities, so the one that he will bring to you eventually is the one that he has properly scrutinized.', 0.625),
  ('singleness', 80536, 'e__NgpSPXqI', 3974.06, 4051.73, 'Not be in haste', 'One of the evidence that you have heard God is that you will not be in haste.', 0.618),
  ('singleness', 35940, 'HfOhe_CCubg', 19540.24, 19608.25, 'God finds you there', 'There is something God has put in you that you ought to be doing until you start doing that thing, it is in the midst of that thing that you''re doing that is where God will come and find you the husband you are looking.', 0.433),
  ('singleness', 22045, 'AQblidcLcN8', 6129.39, 6160.05, 'Marriage activates greatness', 'There are some person that are ordained by God that it is marriage that will activate a dimension of their greatness.', 0.468),
  ('singleness', 25089, 'BqJMIrJhhpU', 11030.34, 11095.77, 'Dream is not the standard', 'Dream is not the standard of determining the will of God. Dream can be an Avenue for God to speak, are we together?', 0.627),
  ('singleness', 15133, '6iQuSWSVGFQ', 9945.18, 9996.05, 'A kind of becoming', 'There is a becoming, there is a kind of person that God will need you to become so that you can fit fully and perfectly into God''s program for your life.', 0.438),
  ('relationships', 34794, 'H6kA_pNHBiE', 8751.63, 8821.04, 'A covenant needs agreement', 'Marriage was a spiritual Covenant and for you to enter into such Covenant there must be a platform where mutually there''s an agreement before you can begin that Covenant process.', 0.626),
  ('relationships', 2288, '0COgu1AbjA8', 575.83, 630.76, 'Satisfied before relationship', 'I rather be single and satisfied before I go into any relationship for a man that is truly pressing into God.', 0.643),
  ('relationships', 19784, '9ArFEM_08v8', 12575.54, 12739.89, 'Agreement in marriage', 'The marriage covenant is a thing of agreement of two people that are consenting together.', 0.614),
  ('relationships', 114571, 'xBer1ZEM9SA', 11248.08, 11348.0, 'Take it to the Lord', 'You take it to the Lord in prayer, Lord what should I do when should I do this and he will give you a direction on when to do it.', 0.595),
  ('relationships', 114544, 'xBer1ZEM9SA', 7851.92, 7911.27, 'Be sincere in marriage', 'That''s why we talk about the virtue of sincerity. We are actually supposed to be Christians, we''re supposed to be open books, we''re supposed to be sincere people.', 0.614),
  ('relationships', 19620, '95wvmQHBv8M', 7191.25, 7302.54, 'Wait without haste', 'The Bible say he that believe shall not make haste. If you are convinced that this is the person, as long as she is not yet married, you may be willing to wait.', 0.571),
  ('offence', 27126, 'Cucf_wXk9o0', 5372.24, 5424.88, 'Give none offense', 'Give none offense neither to the Jews nor to the Gentiles nor to the Church of God.', 0.547),
  ('offence', 28741, 'DvPFPLKs34I', 8849.92, 8948.55, 'Watch offense in your heart', 'You need to watch offense in your heart. Jesus spoke to the Disciples of John, he said blessed is he that is not offended in me.', 0.543),
  ('offence', 93929, 'm9QGKcA7yf0', 8161.32, 8214.37, 'Meek and unoffended', 'Being Meek means not offending and not easily offended.', 0.539),
  ('offence', 115707, 'xzZj2gzHiGc', 8935.29, 9009.05, 'Offense is inevitable', 'One of the greatest challenge I''ve observed in Ministry is what Jesus addressed. He said it''s unfortunate, but offense is an inevitability, if it''s a reason to be offended you are looking for you don''t need to wait long, it''s a must offense must come.', 0.517),
  ('offence', 74181, 'bgFSU-jSbXQ', 3448.96, 3540.94, 'Show mercy when offended', 'There is no way you can go through life without encountering offense, people offending you and probably you offending someone. Part of the proofs that the Lord has prospered in your heart is that it''s easy for you to show mercy.', 0.474),
  ('offence', 83229, 'gEQqW7sCHuI', 11308.82, 11363.11, 'Rise above offenses', 'Many brethren are broken and are divided from the fellowship because they are offended.', 0.462),
  ('spiritual-attack', 19071, '8iaDksRc3lY', 4834.44, 4866.24, 'Resist every attack', 'Take a decisive stand against him and resist his every attack with strong, vigorous faith.', 0.654),
  ('spiritual-attack', 20651, '9d2iAWitCwU', 10525.35, 10638.55, 'Resist the devil', 'Be sober, be vigilant because your adversary the devil as a roaring lion walketh about seeking whom he may devour, whom resist steadfast in faith.', 0.647),
  ('spiritual-attack', 57508, 'Ss3pRnHlLYQ', 3062.16, 3092.68, 'Stand Against Wiles', 'Put on the whole armor of God that you may be able to stand against the wiles of the devil, not the power of the devil.', 0.63),
  ('spiritual-attack', 57817, 'T2JsKpQgUxs', 9837.07, 9960.91, 'Persistent resistance', 'A persistence, an insistence, there''s a stubborn disposition that a Christian must have in the face of the day-to-day challenges you face on account of the finished work of Jesus.', 0.683),
  ('spiritual-attack', 70027, 'ZX6Pclkydp8', 4466.5, 4563.23, 'Having done all to stand', 'Take unto you the whole armor of God, that he may be able to withstand in the evil day, and having done all to stand.', 0.664),
  ('spiritual-attack', 57829, 'T2JsKpQgUxs', 11380.6, 11430.79, 'Standing is warfare', 'The language of standing is the language of warfare. You are seated with Christ in Heavenly places but you stand against principalities and powers and against all the power of the devil.', 0.651),
  ('burnout', 80184, 'eQNSiRxg3bw', 14970.58, 14996.87, 'Strength for those who wait', 'They that wait upon the Lord shall renew their strength.', 0.533),
  ('burnout', 196251, 'c-RIYKgCbUg', 1334.37, 1401.74, 'Cry for God''s help', 'Assess yourself before the Lord and cry before him. Here am I, oh God. Empty without you. I am empty. I am empty. I need your help.', 0.532),
  ('burnout', 106423, 't1vhpSAXJ9w', 9330.01, 9370.36, 'Rest and quietness', 'In returning and in rest ye shall be saved and in quietness and confidence shall be your strength.', 0.542),
  ('burnout', 94593, 'mQBaMvd0P1o', 1148.73, 1187.23, 'Retain your rest', 'You have to fight to retain your rest, you have to fight to retain your Thanksgiving, you have to fight to retain your heart of rejoicing. Let nothing take that away from you.', 0.534),
  ('burnout', 25153, 'Bt-zSO1nb-s', 2608.04, 2747.87, 'New assignments renew', 'God wants to help you, he gives you new assignments, new responsibilities that will Quicken and activate you again as you used to know.', 0.527),
  ('holy-spirit', 110279, 'uvF2ZqI_ohw', 10811.9, 10925.26, 'The Holy Spirit is a person', 'We are not just talking about power, we are talking of a person, a person who talks, a person with feelings, a person that can be grieved.', 0.654),
  ('holy-spirit', 45260, 'MdUYn8qw5uM', 6252.13, 6323.18, 'Make Him your best friend', 'I want to make the Holy Spirit my best friend. I want to choose him as my best friend.', 0.636),
  ('holy-spirit', 100749, 'qKvh2zWhpkk', 4673.45, 4750.85, 'Yield for direction', 'The more I yield to him, the more his Spirit can find expression through my vessel. The more I yield to him, the more his Spirit is willing to give me direction in situations where my human wisdom fails.', 0.599),
  ('holy-spirit', 45264, 'MdUYn8qw5uM', 6704.32, 6861.81, 'Close the distance', 'Close the distance between you and the Holy Spirit, because there is no way you get a revelation of God Almighty or a revelation of the Lord Jesus without him.', 0.622),
  ('holy-spirit', 34496, 'Gw6MMqMJfog', 3010.99, 3046.05, 'He talks every day', 'I talk to Him every day, He talks to me every day, and I know His voice because I know He''s a person, and I know He indwells me, and He''s closer to me than my wife.', 0.601),
  ('holy-spirit', 118316, 'zQTqjtlyjwM', 690.42, 783.42, 'Know Him deeply', 'Everything that God wants to give us was packaged into that personality called the Holy Spirit. You must know Him, you must know how He functions, you must know the laws in His realm.', 0.597),
  ('holy-spirit', 53521, 'QjDBa6fcjxk', 1935.02, 2031.6, 'Another Comforter', 'I will pray the Father, and he shall give you another Comforter, that he may abide with you forever.', 0.603),
  ('holy-spirit', 51036, 'PXJp-TsydV4', 5867.43, 5933.68, 'The Spirit guides truth', 'When he, the Spirit of truth, is come, he will guide you into all truth.', 0.601),
  ('holy-spirit', 106216, 'sxVZ7A4TRw0', 7370.88, 7528.27, 'Know God intimately', 'It is through that infrastructure, namely the presence and the person of the Holy Ghost, that you can know things that are domiciled in the realm of God so intimately.', 0.605),
  ('holy-spirit', 1000, '-VxddgaYe9o', 657.3, 757.75, 'Not left as orphans', 'Jesus said I will not leave you as orphans. That''s not what I intend, that''s not what I desire, because I don''t want you guys to be orphans.', 0.616),
  ('holy-spirit', 13516, '5uPZAOOWc60', 968.36, 1050.9, 'Hidden in the Spirit', 'Everything that God wants to give you, everything that God believes you need in order to prosecute your destiny, God decided to hide it in the Holy Spirit.', 0.598),
  ('holy-spirit', 84350, 'gpxAG717j3c', 1239.28, 1343.87, 'The Spirit powers you', 'It''s the Holy Ghost that powers your spirit. If it''s not working with your spirit, your spirit is dead because he cannot attain to his potential as ordained by God.', 0.62),
  ('bible', 57666, 'SyuqvJ2blDc', 8785.24, 8872.83, 'Study with outlines', 'When you make it a habit to start studying your Bible with outlines, it becomes easy for you to fall in love with reading the Bible.', 0.568),
  ('bible', 87767, 'j0BaVDoGoDk', 9196.73, 9311.64, 'Need the Holy Spirit', 'Any portion of scripture you approach without the help of the Holy Spirit is like a textbook turned upside down, you''re not going to get anything from it.', 0.503),
  ('bible', 13712, '5x2GqobSJJQ', 6608.22, 6737.28, 'Sit on the truth', 'So when you lay hold on the truth you don''t just add it to a library of knowledge, you sit on it, set your mind and affection on it, and allow your spirit to internalize it.', 0.586),
  ('bible', 87774, 'j0BaVDoGoDk', 10281.87, 10313.8, 'Learn meditation', 'When you approach God''s word what I encourage you to do is to learn the art of meditation.', 0.564),
  ('new-believer', 64222, 'WCB6o3kBGQk', 7040.76, 7155.17, 'Jesus must own your life', 'If the Jesus you accepted has not become the owner of your life you have been deceived.', 0.617),
  ('new-believer', 43837, 'Lxu4HOL1cYI', 2943.79, 3039.93, 'Life by the Holy Ghost', 'So if you don''t have an overflowing measure of the Holy Ghost, you cannot live this kind of life that the Bible speaks about.', 0.645),
  ('new-believer', 43115, 'LLw5PF21JE0', 7209.54, 7258.02, 'Turn to Jesus', 'I turn away from those sins and I Turn to You Jesus because I believe in my heart you came to die for my sins and you were buried.', 0.572),
  ('new-believer', 66633, 'XU-weol4uho', 501.14, 687.4, 'Cure for sin', 'The cure for a life of sin is getting infused with the Holy Ghost. He will destroy the appetite that sustains the sin.', 0.615),
  ('new-believer', 12565, '5CDTASXqhXk', 4458.18, 4543.11, 'Christ dwells in you', 'The moment you gave your life to Christ Jesus Christ dwells in you through his Spirit. It is him you are dealing with when you deal with the Holy Ghost.', 0.608);
insert into public.moments (youtube_id, passage_id, need_id, at_s, end_s, title, quote, score)
