-- Curated moments for the "What are you going through?" needs: 253 moments, 36 needs,
-- 229 sermons. Generated by curated-sermons/pipelines/embeddings/aao_embed/moments.py
-- (match_passages for each need's label and a teaching rephrase, a model review for relevance, a
-- verbatim quote and a title, then hand grading). Re-generate there rather than editing by hand.
--
-- Every quote is a contiguous verbatim span of the passage's YouTube auto-captions with only
-- capitalisation and punctuation added (checked in code, and again by the moments_check_quote
-- trigger). at_s is about 3 s before the quote's first word (caption-line timing); end_s is the
-- passage end, or 20 s after the quote when that is later.
--
-- Idempotent, keyed on (need_id, passage_id): re-running updates these rows in place and adds
-- missing ones. It never deletes; moments.py push(prune=True) removes rows a later run drops.
-- Rows whose passage is not in public.passages (sermon not in the catalogue) are skipped.
-- Requires needs.sql and the passages load.

begin;

create temporary table seed_moments (
  need_id text, passage_id bigint, youtube_id text, at_s real, end_s real, title text, quote text, score real
) on commit drop;


update public.moments m set
  youtube_id = s.youtube_id, at_s = s.at_s, end_s = s.end_s, title = s.title, quote = s.quote, score = s.score
from seed_moments s
where m.need_id = s.need_id and m.passage_id = s.passage_id
  and (m.youtube_id, m.at_s, m.end_s, m.title, m.quote, m.score)
      is distinct from (s.youtube_id, s.at_s, s.end_s, s.title, s.quote, s.score);

select s.youtube_id, s.passage_id, s.need_id, s.at_s, s.end_s, s.title, s.quote, s.score
from seed_moments s
where exists (select 1 from public.passages p where p.id = s.passage_id and p.youtube_id = s.youtube_id)
  and exists (select 1 from public.needs n where n.id = s.need_id)
  and not exists (select 1 from public.moments m where m.need_id = s.need_id and m.passage_id = s.passage_id);

commit;
